--region define
local CatHouseCaptureTextureComplete = Constants.EventNames.CatHouseCaptureTextureComplete
--endregion

--- from: Assets/BundleResources/Prefabs/OverseaManage/OverseaManageCatballControlDialog.prefab
---@class OverseaManageCatBallControlCell
---@field Env                           	OverseaManageCatBallControlCell         
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field ImgSelect                     	UnityEngine.RectTransform               
---@field NotGet                        	UnityEngine.RectTransform               
---@field TextNumber                    	TMPro.TextMeshProUGUI                   
---@field StarGroup                     	UnityEngine.RectTransform               
---@field HasGet                        	UnityEngine.RectTransform               
---@field ImgCatballIcon                	UnityEngine.UI.RawImage                 
---@field ImgQualityBg                  	Game.Native.Common.UISwitchImage        
---@field Catball                       	UnityEngine.RectTransform               
---@field GoodNode                      	UnityEngine.RectTransform               
---@field Goods                         	UnityEngine.RectTransform               
---@field BtnNode                       	UnityEngine.RectTransform               
local OverseaManageCatBallControlCell = Class('OverseaManageCatBallControlCell')

function OverseaManageCatBallControlCell:__init()
end

function OverseaManageCatBallControlCell:__delete()

end

function OverseaManageCatBallControlCell:Awake()
    KTool.SetActive(self.ImgCatballIcon.gameObject, false)
end

function OverseaManageCatBallControlCell:Start()
    SetButtonAction(self.BtnNode.gameObject, Bind(self, self.OnClickBtnNodeAction))
end

function OverseaManageCatBallControlCell:OnDestroy()
    if self.__EventCaptureTextureCompleteAction then
        Events.RemoveListener(CatHouseCaptureTextureComplete, self.__EventCaptureTextureCompleteAction)
        self.__EventCaptureTextureCompleteAction = nil
    end
    
    self.controller = nil--luabehaviour 中CSharp
    self:Delete()
    self = nil
end

--region init

--endregion


--region cultivate

---FreshCultivateUI
---@param data table{
---     vo: MaidCoffeeCatRollConfigVo
--      catData: OverseaCafe/catHome CatList子数据
--      quality: MaidCoffeeCatRollConfigVo.quality
---}
function OverseaManageCatBallControlCell:FreshCultivateUI(data, index)
    self._index = index
    KTool.SetActive(self.Goods.gameObject, false)
    KTool.SetActive(self.Catball.gameObject, true)
    self:FreshCatRoll(data)

    local catData  = data.catData
    local isOwnCat = catData ~= nil
    KTool.SetActive(self.HasGet.gameObject, isOwnCat)
    KTool.SetActive(self.NotGet.gameObject, not isOwnCat)

    if isOwnCat then
        self:FreshStars(catData.star)
        self.TextNumber.text = catData.level
    end
    
end

function OverseaManageCatBallControlCell:FreshStars(star)
    ---@type OverseaManageCatBallStarGroup
    local env = CfUtils.GetLuaScr(self.StarGroup, MaidCoffeeConstants.EnvPath.OverseaManageCatBallStarGroup)
    if not isNull(env) then
        env:FreshUI(star)
    end
    
end

--endregion

--region StoreHouse

function OverseaManageCatBallControlCell:FreshStoreHouseUI(data, index)
    self._index = index
    local goodsNum           = data.goodsNum
    
    --- 有goodsNum 就是道具
    local isGoods = goodsNum ~= nil
    KTool.SetActive(self.Goods.gameObject, isGoods)
    KTool.SetActive(self.GoodNode.gameObject, isGoods)
    KTool.SetActive(self.Catball.gameObject, not isGoods)

    if isGoods then
        self:FreshGoods(data)
    else
        KTool.SetActive(self.HasGet.gameObject, false)
        KTool.SetActive(self.NotGet.gameObject, false)
        self:FreshCatRoll(data)
    end
end

function OverseaManageCatBallControlCell:FreshGoods(data)
    ---@type GoodsVo
    local goodsVo = data.vo
    local goodsId = goodsVo.id
    CfUtils.RefeshGoodGo(self.GoodNode, goodsId, string.format("X%s", data.goodsNum), 0.75)
end

--endregion

--region Common

function OverseaManageCatBallControlCell:FreshCatRoll(data)
    local quality            = data.quality
    self.ImgQualityBg.Status = quality
    self:RegEvent()
    local genes = data.catData ~= nil and data.catData.genes or data.vo.kind1
    self:CaptureTexture(data.vo.catId, genes)
end

function OverseaManageCatBallControlCell:FreshSelectState(isSelect)
    KTool.SetActive(self.ImgSelect.gameObject, isSelect)
    
end


function OverseaManageCatBallControlCell:RegEvent()
    if self.__EventCaptureTextureCompleteAction then
        return
    end
    self.__EventCaptureTextureCompleteAction = Events.AddListener(CatHouseCaptureTextureComplete, Bind(self, self.OnEventCaptureTextureCompleteAction))
end

function OverseaManageCatBallControlCell:CaptureTexture(catId, genes)
    ---@type CatEggComponent
    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    local fileNameId = eggComponent:GetFileNameId(MaidCoffeeConstants.BornType.Adult, catId, genes)
    self._fileNameId = fileNameId
    eggComponent:CaptureTexture(MaidCoffeeConstants.BornType.Adult, checkNumber(catId), genes,false, fileNameId)
end

--endregion


--region get/set
function OverseaManageCatBallControlCell:SetCallback(cb)
    self._callback = cb
end

--endregion


--region handler

function OverseaManageCatBallControlCell:OnClickBtnNodeAction()
    if self._callback then
        self._callback(self._index)
    end
end


function OverseaManageCatBallControlCell:OnEventCaptureTextureCompleteAction(id, path)
    if self._fileNameId ~= id then return end
    ---@type CatEggComponent
    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    local texture = eggComponent:LoadCaptureTexture(path, false)
    self.ImgCatballIcon.texture = texture
    KTool.SetActive(self.ImgCatballIcon.gameObject, true)
end
--endregion

return OverseaManageCatBallControlCell